import{_ as s,C as n,c as a,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const k=JSON.parse('{"title":"Backorders and returns","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/operations/backorders-and-returns.md","filePath":"master/supply-chain/inventories/operations/backorders-and-returns.md","lastUpdated":1791902625000}'),d={name:"master/supply-chain/inventories/operations/backorders-and-returns.md"};function l(h,e,c,u,g,p){const r=n("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="backorders-and-returns" tabindex="-1">Backorders and returns <a class="header-anchor" href="#backorders-and-returns" aria-label="Permalink to &quot;Backorders and returns&quot;">​</a></h1><p>Real life is rarely perfect. A vendor ships fewer goods than ordered, or a customer sends products back. Aureus handles the first with backorders and the second with returns.</p><blockquote><p><strong>In simple words:</strong> A backorder is the leftover part of a transfer for later. A return is a new transfer that undoes a finished one.</p></blockquote><h2 id="backorders" tabindex="-1">Backorders <a class="header-anchor" href="#backorders" aria-label="Permalink to &quot;Backorders&quot;">​</a></h2><p>A backorder is a new transfer for the quantity that was not processed. If <strong>WH/IN/11</strong> expects 15 <strong>SSD 512GB</strong> and only 10 arrive, the missing 5 can wait in a new receipt, like <strong>WH/IN/15</strong>.</p><h3 id="the-create-backorder-setting" tabindex="-1">The Create Backorder setting <a class="header-anchor" href="#the-create-backorder-setting" aria-label="Permalink to &quot;The Create Backorder setting&quot;">​</a></h3><p>Each <a href="./../warehouses/operation-types.html">operation type</a> has <strong>Create Backorder</strong>. It decides what happens when you validate with less than the demand.</p><table tabindex="0"><thead><tr><th>Option</th><th>Result</th></tr></thead><tbody><tr><td><strong>Ask</strong></td><td>A window asks you each time. This is the default.</td></tr><tr><td><strong>Always</strong></td><td>A backorder is created without asking.</td></tr><tr><td><strong>Never</strong></td><td>No backorder. The remaining demand is dropped.</td></tr></tbody></table><p>Point of sale operation types use <strong>Never</strong>.</p><h3 id="the-window" tabindex="-1">The window <a class="header-anchor" href="#the-window" aria-label="Permalink to &quot;The window&quot;">​</a></h3><p>With <strong>Ask</strong>, clicking <strong>Validate</strong> on a short transfer opens <strong>Create Back Order?</strong>. If you edited the lines, click <strong>Save changes</strong> first, then click <strong>Validate</strong>. The text reads: &quot;Create a backorder if the remaining products will be processed later. If not, do not generate a backorder.&quot;</p>',11)),o(r,{src:"/images1/inventory/bo_modal.png",alt:"Create Back Order window with Cancel, No Backorder (red) and Confirm (blue) buttons"}),e[1]||(e[1]=t('<p>The buttons sit in this order: <strong>Cancel</strong>, <strong>No Backorder</strong> (red) and <strong>Confirm</strong> (blue).</p><ul><li><strong>Cancel:</strong> closes the window. Nothing changes.</li><li><strong>No Backorder:</strong> processes what you entered and discards the rest.</li><li><strong>Confirm:</strong> processes what you entered and creates a backorder for the rest.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Choose <strong>Confirm</strong> when the vendor will send the rest. Choose <strong>No Backorder</strong> when the order is closed.</p></div><p>On the transfers list, the backorder is a new record with the same <strong>Source Document</strong>. Group by <strong>Source Document</strong> to see them together.</p><h2 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h2><p>A return sends goods back after a transfer is <strong>Done</strong>. Customers return deliveries. You return receipts to vendors.</p><ol><li>Open the done transfer, for example receipt <strong>WH/IN/12</strong>.</li><li>Click <strong>Return</strong>. The window titled <strong>Return</strong> opens.</li><li>The table has the columns <strong>Product</strong>, <strong>Quantity</strong> and <strong>UOM</strong>, and a red delete icon on each row. For each product, type the <strong>Quantity</strong> to return (the field shows the placeholder <strong>Qty</strong>). Click the red icon to remove a row you do not want to return.</li></ol>',7)),o(r,{src:"/images1/inventory/ret_modal.png",alt:"Return window for WH/IN/12 with Laptop Chassis and LCD Screen 14-inch quantities"}),e[2]||(e[2]=t('<ol start="4"><li>Click <strong>Submit</strong>. Click <strong>Cancel</strong> instead to close the window with no return.</li></ol><p>Aureus creates a new transfer in the opposite direction. It uses the <strong>Return Type</strong> of the original operation type. Receipts return through <strong>Delivery Orders</strong>, and deliveries through <strong>Receipts</strong>. Validate that transfer to finish the return.</p><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><ul><li>Only lines in <strong>Done</strong> state that are not fully returned can be returned. Otherwise you see &quot;No products to return&quot;.</li><li>You must enter at least one non-zero quantity.</li><li>A quantity above the processed quantity shows a warning tooltip.</li></ul><h2 id="next-transfer" tabindex="-1">Next Transfer <a class="header-anchor" href="#next-transfer" aria-label="Permalink to &quot;Next Transfer&quot;">​</a></h2><p>On a done transfer that has a follow-up, the <strong>Next Transfer</strong> button opens that next document. For example <strong>WH/IN/12</strong> leads to its storage step. It does not show when no next document exists.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Validate</strong> with <strong>Ask</strong> can create a backorder.</li><li><strong>Return</strong> appears only in <strong>Done</strong>.</li><li><strong>Next Transfer</strong> appears when a follow-up exists.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Transfers</a></li><li><a href="./../warehouses/operation-types.html">Operation types</a></li><li><a href="./receipts.html">Receipts</a></li><li><a href="./deliveries.html">Deliveries</a></li></ul>',10))])}const m=s(d,[["render",l]]);export{k as __pageData,m as default};
